statement:
Decide whether `word` uses capital letters correctly. Correct usage means one of these patterns holds:

- every letter of `word` is uppercase (`"USA"`);
- every letter is lowercase (`"leetcode"`);
- the first letter is uppercase and each letter after it is lowercase (`"Google"`).

Return `true` if the word fits one of the patterns and `false` if it fits none.

validator:
function validate([word]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 100) return 'word needs 1 to 100 letters.';
  if (!/^[A-Za-z]+$/.test(word)) return 'word may contain only English letters.';
  return null;
}

reference:
function detectCapitalUse(word) {
  let capitals = 0;

  for (const ch of word) {
    if (ch >= 'A' && ch <= 'Z') {
      capitals++;
    }
  }

  if (capitals === 0 || capitals === word.length) {
    return true;
  }

  const firstIsCapital = word[0] >= 'A' && word[0] <= 'Z';
  return capitals === 1 && firstIsCapital;
}

brute:
function detectCapitalUse(word) {
  const upper = word.toUpperCase();
  const lower = word.toLowerCase();
  const title = word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
  return word === upper || word === lower || word === title;
}

generator:
function generate(rand, size) {
  const n = size === 'large' ? 60 + Math.floor(rand() * 41) : 1 + Math.floor(rand() * 6);
  const letter = () => String.fromCharCode(97 + Math.floor(rand() * 26));
  let word = Array.from({ length: n }, letter).join('');
  const shape = Math.floor(rand() * 6);
  if (shape === 0) word = word.toUpperCase();
  else if (shape === 1) word = word[0].toUpperCase() + word.slice(1);
  else if (shape === 2) word = word.split('').map(ch => (rand() < 0.5 ? ch.toUpperCase() : ch)).join('');
  else if (shape === 3) {
    // One stray change on an otherwise valid word.
    const chars = (rand() < 0.5 ? word.toUpperCase() : word).split('');
    const at = Math.floor(rand() * n);
    chars[at] = chars[at] === chars[at].toUpperCase() ? chars[at].toLowerCase() : chars[at].toUpperCase();
    word = chars.join('');
  }
  return [word];
}
